mapper.select:
SELECT frr.id, frr.CODE, frr.user_id, frr.merchant_id, frr.STATUS, frr.address_id, frr.type_id, frr.staff_id, frr.furniture_type, frr.content, frr.integral, frr.create_date, ui.name as userName, ui.images as userImages, mi.name as merchantName, mi.images as merchantImages, ai.province, ai.city, ai.area, ai.address, si.name, si.images, rti.name AS repairTypeName FROM furniture_repair_record frr LEFT JOIN user_info ui ON (ui.id = frr.user_id) LEFT JOIN merchant_info mi ON (mi.id = frr.merchant_id) LEFT JOIN staff_info si ON (si.id = frr.staff_id) LEFT JOIN address_info ai ON (ai.id = frr.address_id) LEFT JOIN repair_type_info rti ON (rti.id = frr.type_id) WHERE 1 = 1
AND ui.name LIKE CONCAT('%',#{furnitureRepairRecord.userName},'%')
AND mi.name LIKE CONCAT('%',#{furnitureRepairRecord.merchantName},'%')
AND frr.STATUS = #{furnitureRepairRecord.status}
AND ui.user_id = #{furnitureRepairRecord.userId}
AND mi.user_id = #{furnitureRepairRecord.merchantId}
ORDER BY frr.create_date DESC
